class Solution {
    public int[] countInRange(int[] scores, int[][] queries) {
        int[] out = new int[queries.length];
        for (int q = 0; q < queries.length; q++)
            for (int s : scores)
                if (s >= queries[q][0] && s <= queries[q][1]) out[q]++;
        return out;
    }
}

