from bisect import bisect_left, bisect_right

class Solution:
    def countInRange(self, scores: List[int], queries: List[List[int]]) -> List[int]:
        s = sorted(scores)
        return [bisect_right(s, hi) - bisect_left(s, lo) for lo, hi in queries]

