class Solution {
public:
    vector<int> countInRange(vector<int>& scores, vector<vector<int>>& queries) {
        vector<int> s = scores;
        sort(s.begin(), s.end());
        vector<int> out;
        for (auto& q : queries) {
            auto a = lower_bound(s.begin(), s.end(), q[0]);
            auto b = upper_bound(s.begin(), s.end(), q[1]);
            out.push_back(b - a);
        }
        return out;
    }
};

