static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

// First index whose value is greater than x.
static int firstAbove(const int* a, int n, long long x) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] <= x) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int* countInRange(int* scores, int scoresSize, int** queries, int queriesSize, int* queriesColSize, int* returnSize) {
    int* s = malloc(scoresSize * sizeof(int));
    memcpy(s, scores, scoresSize * sizeof(int));
    qsort(s, scoresSize, sizeof(int), cmpInt);
    int* out = malloc(queriesSize * sizeof(int));
    for (int q = 0; q < queriesSize; q++) {
        out[q] = firstAbove(s, scoresSize, queries[q][1]) - firstAbove(s, scoresSize, (long long) queries[q][0] - 1);
    }
    free(s);
    *returnSize = queriesSize;
    return out;
}
